def is_multiply_prime(a):
    """Check if the given number is the product of exactly 3 prime numbers."""
    if a < 2:
        return False
    factors = []
    d = 2
    while d * d <= a:
        while a % d == 0:
            factors.append(d)
            a //= d
        d += 1
    if a > 1:
        factors.append(a)
    return len(factors) == 3 and all(is_prime(f) for f in factors)

def is_prime(n):
    """Helper function to check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
