def is_simple_power(x, n):
    """Check if x is a simple power of n (i.e., n**int == x)."""
    if x == 1:
        return True
    if n == 1:
        return False
    exponent = 0
    while n ** exponent < x:
        exponent += 1
    return n ** exponent == x
